    "codigo_origem": "Q3588651",
    "numero_original": 20,
    "banca": "SELECON",
    "orgao": "Prefeitura de Lucas do Rio Verde - MT Provas: SELECON - 2024 - Prefeitura de Lucas do Rio Verde -",
